INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_ATTACKED_1','This assault has neither planning approval nor a valid traffic management scheme.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_BOLLARD_HEADING_1','Four Hundred Years of Temporary Works');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_BOLLARD_LIVED','Until further notice');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_BOLLARD_NAME','High Marshal Bollard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_BOLLARD_SUBTITLE','Supreme Overseer of the Conical Union');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_BOLLARD_TEXT_1','High Marshal Bollard is a towering orange traffic cone decorated with ceremonial reflective stripes. He governs from a throne assembled from discarded traffic signs, where every audience begins with a site-safety briefing.[NEWLINE][NEWLINE]His greatest achievement was keeping the same highway closed for four hundred consecutive years. Successive commissions praised the consistency of the signage. Under his direction, the Union became a remarkably effective state, provided one could reach the appropriate office.');
