INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_CIV','The Conical Union');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_CIV5_HEADING_1','A Well-Administered Obstruction');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_CIV5_TEXT_1','The Conical Union is a society of sentient traffic cones whose administrative competence is matched only by its commitment to road closures. Its citizens regard infrastructure as a public trust and a properly authorized obstruction as a civic virtue.[NEWLINE][NEWLINE]Roads bind its settlements into a productive empire. The Union pays normal upkeep, observes ordinary construction rules and insists that every project carry the correct permit. A closure marked temporary may outlast the civilization that requested it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_CIV_PEDIA','The Conical Union is a society of sentient traffic cones whose administrative competence is matched only by its commitment to road closures. Its citizens regard infrastructure as a public trust and a properly authorized obstruction as a civic virtue.[NEWLINE][NEWLINE]Roads bind its settlements into a productive empire. The Union pays normal upkeep, observes ordinary construction rules and insists that every project carry the correct permit. A closure marked temporary may outlast the civilization that requested it.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_DAWN','High Marshal Bollard, Supreme Overseer of the Conical Union![NEWLINE][NEWLINE]For centuries, your people have stood proudly upon the roads of the world, directing travelers, protecting construction sites and occasionally causing entirely unnecessary traffic congestion.[NEWLINE][NEWLINE]Now, the cones have awakened.[NEWLINE][NEWLINE]No longer shall your people be moved aside by careless travelers.[NEWLINE][NEWLINE]Build your roads. Establish your offices. Connect the world beneath your glorious orange banners.[NEWLINE][NEWLINE]Will your civilization stand the test of time, or shall it be removed by an irritated construction worker?');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_DEFEAT_1','After careful consideration... we have decided to reopen the road.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_DUMMY','Connected Administration');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_DUMMY_HELP','Automatically maintained connection yields. Cannot be constructed, purchased or sold.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_FRIENDLY_1','Your permit is in order. Welcome back to the approved meeting area.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_GREETING_1','Greetings, traveler. Unfortunately, this diplomatic meeting is taking place within an active construction zone. Please proceed with caution.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_HOSTILE_1','Your repeated failure to observe the signage has been entered into the permanent record.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_LEADER','High Marshal Bollard');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_LEADER_PEDIA','High Marshal Bollard is a towering orange traffic cone decorated with ceremonial reflective stripes. He governs from a throne assembled from discarded traffic signs, where every audience begins with a site-safety briefing.[NEWLINE][NEWLINE]His greatest achievement was keeping the same highway closed for four hundred consecutive years. Successive commissions praised the consistency of the signage. Under his direction, the Union became a remarkably effective state, provided one could reach the appropriate office.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_NEUTRAL_1','Take a number. The High Marshal will review your application shortly.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_OFFICE','Detour Office');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_OFFICE_HELP','Replaces Walls and retains all active Community Patch Walls benefits and requirements. Adds +1 [ICON_CULTURE] Culture permanently. A connected non-capital city with a real Detour Office also receives +2 [ICON_GOLD] Gold. The Capital never receives this conditional Gold. Connection bonuses follow native network refresh and reconciliation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_OFFICE_PEDIA','Every Detour Office contains defensive masonry, a public counter and a registry of roads that may eventually reopen. Its clerks consider a well-posted diversion a cultural achievement. Connected branches collect ordinary administrative fees; the central office is strictly a cost center.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_OFFICE_STRATEGY','Build Detour Offices to defend settlements and gain permanent Culture. Connect non-capital cities to add Gold. A disconnected Office keeps its Culture and inherited Walls benefits. The Capital can build an Office but receives no connection Gold.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_PEACE_1','Hostilities are suspended pending final inspection. Please observe the temporary speed limit.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_PEACE_OFFER_1','The demolition budget has been reviewed. We propose reopening diplomatic access.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SHORT','The Conical Union');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_1','Inspector Chevron');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_10','Commissioner Stop');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_2','Agent Contraflow');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_3','Surveyor Plumb');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_4','Clerk Chicane');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_5','Auditor Amber');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_6','Officer Verge');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_7','Marshal Taper');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_8','Warden Kerb');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_SPY_9','Examiner Median');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_STRATEGY','Connect an expanding empire to turn infrastructure into flat Production and Culture. Road Crews develop every normal improvement faster. Detour Offices retain Walls defenses, add permanent Culture and provide conditional Gold outside the Capital. Growth and production support Science or conventional Domination; the civilization has no direct Science or combat bonus. Its starting Capital receives no ability yields, and broken connections disrupt its economy.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_TRADE_1','All copies have been stamped. The exchange may proceed.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_TRAIT','Sorry for the Inconvenience');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_TRAIT_HELP','Every non-capital city connected to the Capital receives +2 [ICON_PRODUCTION] Production and +1 [ICON_CULTURE] Culture. Uses native city connections, including qualifying Harbors. Bonuses update at lifecycle events and owner-turn reconciliation after native network refresh; see the guide for timing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_UNIT','Road Crew');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_UNIT_HELP','Replaces Worker. Retains the active Community Patch Worker rules, with +1 Movement and +25% base Work Rate for all ordinary Worker actions, including roads and repairs. Native integer rounding applies.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_UNIT_PEDIA','A Road Crew carries the authority of the Department of Temporary Permanent Works. Its members erect barriers with precision, lay roads with admirable speed and file a separate incident report for every stone. Their speed does not exempt the Union from normal construction requirements or road maintenance.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_UNIT_STRATEGY','Send Road Crews ahead of expansion to improve resources and connect new cities. Their additional Movement and 25% higher base Work Rate apply throughout their normal Worker duties. They receive no combat bonuses or free roads.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_CONICAL_WAR_1','Your empire has been designated an unauthorized construction project. Demolition begins immediately.');
